create policy "store img admin insert" on storage.objects for insert to authenticated with check (bucket_id = 'store-images' and public.has_role(auth.uid(),'admin'));
create policy "store img admin update" on storage.objects for update to authenticated using (bucket_id = 'store-images' and public.has_role(auth.uid(),'admin'));
create policy "store img admin delete" on storage.objects for delete to authenticated using (bucket_id = 'store-images' and public.has_role(auth.uid(),'admin'));